long long countInversions(vector<int> nums) {
    vector<int> buffer(nums.size());
    function<long long(int, int)> countRange = [&](int left, int right) -> long long {
        if (right - left < 2) return 0;
        int middle = left + (right - left) / 2;
        long long count = countRange(left, middle) + countRange(middle, right);
