long long countReversePairs(vector<int> nums) {
    vector<int> buffer(nums.size());
    function<long long(int, int)> countRange = [&](int left, int right) -> long long {
        if (right - left < 2) return 0;
        int middle = left + (right - left) / 2;
        long long count = countRange(left, middle) + countRange(middle, right);
        int j = middle;
        for (int i = left; i < middle; ++i) {
            while (j < right && static_cast<long long>(nums[i]) > 2LL * nums[j]) ++j;
            count += j - middle;
        }
        int i = left, write = left;
        j = middle;
        while (i < middle && j < right) {
            buffer[write++] = nums[i] <= nums[j] ? nums[i++] : nums[j++];
        }
        while (i < middle) buffer[write++] = nums[i++];
        while (j < right) buffer[write++] = nums[j++];
        copy(buffer.begin() + left, buffer.begin() + right, nums.begin() + left);
        return count;
    };
    return countRange(0, static_cast<int>(nums.size()));
}

