using namespace std;

string minimumWindow(const string& text, const string& required) {
    if (required.empty()) return "";
    array<int, 256> needed{};
    for (unsigned char ch : required) ++needed[ch];
    int missing = required.size(), left = 0, bestStart = 0, bestLength = INT_MAX;
    for (int right = 0; right < static_cast<int>(text.size()); ++right) {
        unsigned char ch = text[right];
        if (needed[ch] > 0) --missing;
        --needed[ch];
        while (missing == 0) {
            if (right - left + 1 < bestLength) {
                bestStart = left;
                bestLength = right - left + 1;
            }
            unsigned char removed = text[left++];
            if (++needed[removed] > 0) ++missing;
        }
    }
    return bestLength == INT_MAX ? "" : text.substr(bestStart, bestLength);
}

