#include <unordered_map>
#include <vector>
using namespace std;

long long subarraysWithKDistinct(const vector<int>& nums, int k) {
    auto atMost = [&](int limit) -> long long {
        if (limit < 0) return 0;
        unordered_map<int, int> frequency;
        int left = 0;
        long long count = 0;
        for (int right = 0; right < static_cast<int>(nums.size()); ++right) {
            ++frequency[nums[right]];
            while (static_cast<int>(frequency.size()) > limit) {
                int removed = nums[left++];
                if (--frequency[removed] == 0) frequency.erase(removed);
            }
            count += right - left + 1;
        }
        return count;
    };
    return atMost(k) - atMost(k - 1);
}

