#include <algorithm>
using namespace std;

struct ListNode {
    int val;
    ListNode* next;
    explicit ListNode(int value = 0, ListNode* following = nullptr)
        : val(value), next(following) {}
};

bool isPalindromeList(ListNode* head) {
    if (!head || !head->next) return true;
    auto reverse = [](ListNode* node) {
        ListNode* previous = nullptr;
        while (node) {
            ListNode* next = node->next;
            node->next = previous;
            previous = node;
            node = next;
        }
        return previous;
    };
    ListNode* firstHalfEnd = head;
    ListNode* fast = head;
    while (fast->next && fast->next->next) {
        firstHalfEnd = firstHalfEnd->next;
        fast = fast->next->next;
    }
    ListNode* secondHalf = reverse(firstHalfEnd->next);
    ListNode* left = head;
    ListNode* right = secondHalf;
    bool equal = true;
    while (right) {
        if (left->val != right->val) equal = false;
        left = left->next;
        right = right->next;
    }
    firstHalfEnd->next = reverse(secondHalf);
    return equal;
}

