using namespace std;

vector<string> generateParentheses(int n) {
    vector<string> result;
    string current;
    function<void(int, int)> visit = [&](int opened, int closed) {
        if (opened == n && closed == n) {
            result.push_back(current);
            return;
        }
        if (opened < n) {
            current.push_back('(');
            visit(opened + 1, closed);
            current.pop_back();
