using namespace std;

vector<vector<string>> palindromePartitions(const string& text) {
    int n = text.size();
    vector<vector<bool>> palindrome(n, vector<bool>(n, false));
    for (int left = n - 1; left >= 0; --left) {
        for (int right = left; right < n; ++right) {
            palindrome[left][right] = text[left] == text[right] && (right - left < 2 || palindrome[left + 1][right - 1]);
        }
    }
    vector<vector<string>> partitions;
    vector<string> current;
    function<void(int)> visit = [&](int start) {
        if (start == n) {
            partitions.push_back(current);
            return;
        }
        for (int end = start; end < n; ++end) {
            if (!palindrome[start][end]) continue;
            current.push_back(text.substr(start, end - start + 1));
            visit(end + 1);
            current.pop_back();
        }
    };
    visit(0);
    return partitions;
}

