        for (int end = index + 1; end <= min(static_cast<int>(digits.size()), index + 3); ++end) {
            string segment = digits.substr(index, end - index);
            if (segment.size() > 1 && segment.front() == '0') break;
            if (stoi(segment) > 255) break;
            segments.push_back(segment);
            search(end);
            segments.pop_back();
        }
    };
    search(0);
    return answer;
}

