using namespace std;

int countNQueens(int n) {
    unordered_set<int> columns, descending, ascending;
    function<int(int)> place = [&](int row) {
        if (row == n) return 1;
        int count = 0;
        for (int col = 0; col < n; ++col) {
            if (columns.count(col) || descending.count(row - col) || ascending.count(row + col)) continue;
            columns.insert(col);
            descending.insert(row - col);
            ascending.insert(row + col);
            count += place(row + 1);
            columns.erase(col);
            descending.erase(row - col);
            ascending.erase(row + col);
        }
        return count;
    };
    return place(0);
}

