string kthPermutation(int n, int k) {
    vector<int> available(n), factorial(n + 1, 1);
    iota(available.begin(), available.end(), 1);
    for (int i = 1; i <= n; ++i) factorial[i] = factorial[i - 1] * i;
    --k; // Work with a zero-based permutation rank.
    string result;
    for (int remaining = n; remaining > 0; --remaining) {
        int index = k / factorial[remaining - 1];
        result += to_string(available[index]);
        available.erase(available.begin() + index);
        k %= factorial[remaining - 1];
    }
    return result;
}

