vector<int> anticlockwiseBoundary(TreeNode* root) {
    if (!root) return {};
    auto isLeaf = [](TreeNode* node) {
        return node && !node->left && !node->right;
    };
    vector<int> boundary{root->val};
    for (TreeNode* node = root->left; node; node = node->left ? node->left : node->right) {
        if (!isLeaf(node)) boundary.push_back(node->val);
    }
    function<void(TreeNode*)> appendLeaves = [&](TreeNode* node) {
        if (!node) return;
        if (isLeaf(node)) {
            boundary.push_back(node->val);
            return;
        }
        appendLeaves(node->left);
        appendLeaves(node->right);
    };
    if (!isLeaf(root)) {
        appendLeaves(root->left);
        appendLeaves(root->right);
    }
    vector<int> rightBoundary;
    for (TreeNode* node = root->right; node; node = node->right ? node->right : node->left) {
        if (!isLeaf(node)) rightBoundary.push_back(node->val);
    }
    reverse(rightBoundary.begin(), rightBoundary.end());
    boundary.insert(boundary.end(), rightBoundary.begin(), rightBoundary.end());
    return boundary;
}

