unsigned long long maximumTreeWidth(TreeNode* root) {
    if (!root) return 0;
    vector<pair<TreeNode*, unsigned long long>> level{{root, 0}};
    unsigned long long widest = 0;
    while (!level.empty()) {
        unsigned long long base = level.front().second;
