};

vector<int> nodesAtDistanceK(TreeNode* root, TreeNode* target, int k) {
    unordered_map<TreeNode*, TreeNode*> parent;
    function<void(TreeNode*, TreeNode*)> indexParents = [&](TreeNode* node, TreeNode* previous) {
        if (!node) return;
        parent[node] = previous;
        indexParents(node->left, node);
        indexParents(node->right, node);
    };
    indexParents(root, nullptr);
    if (!target) return {};
    vector<TreeNode*> frontier{target};
    unordered_set<TreeNode*> seen{target};
    for (int distance = 0; distance < k; ++distance) {
        vector<TreeNode*> next;
        for (TreeNode* node : frontier) {
            for (TreeNode* neighbor : {node->left, node->right, parent[node]}) {
                if (neighbor && seen.insert(neighbor).second) next.push_back(neighbor);
            }
        }
        frontier = std::move(next);
    }
    vector<int> answer;
    for (TreeNode* node : frontier) answer.push_back(node->val);
    sort(answer.begin(), answer.end());
    return answer;
}

