vector<vector<int>> verticalTraversal(TreeNode* root) {
    vector<tuple<int, int, int>> positions; // column, row, value
    function<void(TreeNode*, int, int)> visit = [&](TreeNode* node, int row, int column) {
        if (!node) return;
        positions.emplace_back(column, row, node->val);
        visit(node->left, row + 1, column - 1);
        visit(node->right, row + 1, column + 1);
    };
    visit(root, 0, 0);
    sort(positions.begin(), positions.end());
    vector<vector<int>> columns;
    int previousColumn = 0;
    for (auto [column, row, value] : positions) {
        if (columns.empty() || column != previousColumn) columns.push_back({});
        columns.back().push_back(value);
        previousColumn = column;
    }
    return columns;
}

