class Heap{constructor(cmp=(a,b)=>a-b){this.a=[];this.c=cmp}push(x){const a=this.a;a.push(x);let i=a.length-1;while(i){const p=(i-1)>>1;if(this.c(a[p],a[i])<=0)break;[a[p],a[i]]=[a[i],a[p]];i=p}}pop(){const a=this.a;if(!a.length)return undefined;const v=a[0],z=a.pop();if(a.length){a[0]=z;let i=0;while(true){let j=2*i+1;if(j>=a.length)break;if(j+1<a.length&&this.c(a[j+1],a[j])<0)j++;if(this.c(a[i],a[j])<=0)break;[a[i],a[j]]=[a[j],a[i]];i=j}}return v}get size(){return this.a.length}peek(){return this.a[0]}}const h=new Heap((a,b)=>b-a);for(const x of input)h.push(x);while(h.size>1){const a=h.pop(),b=h.pop();if(a!==b)h.push(a-b)}return h.size?h.pop():0;
}

