#include <stdexcept>
#include <vector>

using namespace std;

int lastStoneWeight(const vector<int>& stones) {
    priority_queue<int> heap(stones.begin(), stones.end());
    while (heap.size() > 1) {
        int first = heap.top();
        heap.pop();
        int second = heap.top();
        heap.pop();
        if (first != second) heap.push(first - second);
    }
    return heap.empty() ? 0 : heap.top();
}

