pair<optional<int>, optional<int>> floorAndCeiling(TreeNode* root, int target) {
    optional<int> floor, ceiling;
    while (root) {
        if (root->val == target) return {target, target};
        if (root->val < target) {
            floor = root->val;
            root = root->right;
        } else {
            ceiling = root->val;
            root = root->left;
        }
    }
    return {floor, ceiling};
}

