long long minimumRopeCost(const vector<int>& ropes) {
    priority_queue<long long, vector<long long>, greater<long long>> heap;
    for (int length : ropes) heap.push(length);
    long long cost = 0;
    while (heap.size() > 1) {
        long long first = heap.top();
        heap.pop();
        long long second = heap.top();
        heap.pop();
        cost += first + second;
        heap.push(first + second);
    }
    return cost;
}

