vector<vector<int>> kClosestPoints(const vector<vector<int>>& points, int k) {
    using Entry = tuple<long long, int, int>; // squared distance, x, y
    priority_queue<Entry> closest;
    for (const auto& point : points) {
        int x = point[0], y = point[1];
        closest.emplace(1LL * x * x + 1LL * y * y, x, y);
        if (static_cast<int>(closest.size()) > k) closest.pop();
    }
    vector<vector<int>> result;
    while (!closest.empty()) {
        auto [distance, x, y] = closest.top();
        closest.pop();
        result.push_back({x, y});
    }
    reverse(result.begin(), result.end());
    return result;
}

