vector<int> mergeSortedLists(const vector<vector<int>>& lists) {
    using Entry = tuple<int, int, int>; // value, list index, element index
    priority_queue<Entry, vector<Entry>, greater<Entry>> heads;
    for (int i = 0; i < static_cast<int>(lists.size()); ++i) {
        if (!lists[i].empty()) heads.emplace(lists[i][0], i, 0);
    }
    vector<int> merged;
    while (!heads.empty()) {
        auto [value, list, index] = heads.top();
        heads.pop();
        merged.push_back(value);
        if (index + 1 < static_cast<int>(lists[list].size())) {
            heads.emplace(lists[list][index + 1], list, index + 1);
        }
    }
    return merged;
}

