pair<int, int> smallestCoveringRange(const vector<vector<int>>& lists) {
    using Entry = tuple<int, int, int>;
    priority_queue<Entry, vector<Entry>, greater<Entry>> heads;
    int high = INT_MIN;
    for (int i = 0; i < static_cast<int>(lists.size()); ++i) {
        heads.emplace(lists[i][0], i, 0);
        high = max(high, lists[i][0]);
    }
    pair<int, int> best{get<0>(heads.top()), high};
    while (!heads.empty()) {
        auto [low, list, index] = heads.top();
        heads.pop();
        auto candidate = make_pair(1LL * high - low, low);
        auto previous = make_pair(1LL * best.second - best.first, best.first);
        if (candidate < previous) best = {low, high};
        if (index + 1 == static_cast<int>(lists[list].size())) break;
        int next = lists[list][index + 1];
        high = max(high, next);
        heads.emplace(next, list, index + 1);
    }
    return best;
}

