int countEnclaveCells(vector<vector<int>> grid) {
    int rows = static_cast<int>(grid.size()), columns = static_cast<int>(grid[0].size());
    vector<pair<int, int>> pending;
    for (int row = 0; row < rows; ++row) {
        for (int column = 0; column < columns; ++column) {
            if (grid[row][column] &&
                (row == 0 || row == rows - 1 || column == 0 || column == columns - 1)) {
                grid[row][column] = 0;
                pending.push_back({row, column});
            }
        }
    }
    int dr[] = {1, -1, 0, 0}, dc[] = {0, 0, 1, -1};
    for (size_t head = 0; head < pending.size(); ++head) {
        auto [row, column] = pending[head];
        for (int direction = 0; direction < 4; ++direction) {
            int nextRow = row + dr[direction], nextColumn = column + dc[direction];
            if (nextRow >= 0 && nextRow < rows && nextColumn >= 0 && nextColumn < columns &&
                grid[nextRow][nextColumn] == 1) {
                grid[nextRow][nextColumn] = 0;
                pending.push_back({nextRow, nextColumn});
            }
        }
    }
    int count = 0;
    for (const auto& row : grid) count += accumulate(row.begin(), row.end(), 0);
    return count;
}

