int countProvinces(const vector<vector<int>>& connected) {
    int n = static_cast<int>(connected.size()), provinces = 0;
    vector<bool> seen(n, false);
    for (int start = 0; start < n; ++start) {
        if (seen[start]) continue;
        ++provinces;
        vector<int> stack{start};
        seen[start] = true;
        while (!stack.empty()) {
            int vertex = stack.back();
            stack.pop_back();
            for (int neighbor = 0; neighbor < n; ++neighbor) {
                if (connected[vertex][neighbor] && !seen[neighbor]) {
                    seen[neighbor] = true;
                    stack.push_back(neighbor);
                }
            }
        }
    }
    return provinces;
}

