int wordLadderLength(const string& begin, const string& end, const vector<string>& words) {
    unordered_set<string> remaining(words.begin(), words.end());
    if (!remaining.count(end)) return 0;
    vector<pair<string, int>> pending{{begin, 1}};
    remaining.erase(begin);
    for (size_t head = 0; head < pending.size(); ++head) {
        auto [word, length] = pending[head];
        if (word == end) return length;
        for (size_t position = 0; position < word.size(); ++position) {
            string next = word;
            for (char letter = 'a'; letter <= 'z'; ++letter) {
                next[position] = letter;
                if (remaining.erase(next)) pending.push_back({next, length + 1});
            }
        }
    }
    return 0;
}

