int shortestBridge(vector<vector<int>> grid) {
    int n = static_cast<int>(grid.size());
    int firstRow = -1, firstColumn = -1;
    for (int row = 0; row < n && firstRow == -1; ++row) {
        for (int column = 0; column < n; ++column) {
            if (grid[row][column] == 1) {
                firstRow = row;
                firstColumn = column;
                break;
            }
        }
    }
    int dr[] = {1, -1, 0, 0}, dc[] = {0, 0, 1, -1};
    vector<pair<int, int>> stack{{firstRow, firstColumn}};
    vector<tuple<int, int, int>> pending;
    grid[firstRow][firstColumn] = 2;
    // Mark every cell in the first island, then use all of it as a BFS source.
    while (!stack.empty()) {
        auto [row, column] = stack.back();
        stack.pop_back();
        pending.emplace_back(row, column, 0);
        for (int direction = 0; direction < 4; ++direction) {
            int r = row + dr[direction], c = column + dc[direction];
            if (r >= 0 && r < n && c >= 0 && c < n && grid[r][c] == 1) {
                grid[r][c] = 2;
                stack.push_back({r, c});
            }
        }
    }
    for (size_t head = 0; head < pending.size(); ++head) {
        auto [row, column, distance] = pending[head];
        for (int direction = 0; direction < 4; ++direction) {
            int r = row + dr[direction], c = column + dc[direction];
            if (r < 0 || r >= n || c < 0 || c >= n) continue;
            if (grid[r][c] == 1) return distance;
            if (grid[r][c] == 0) {
                grid[r][c] = 2;
                pending.emplace_back(r, c, distance + 1);
            }
        }
    }
    return -1;
}

