using namespace std;

vector<optional<long long>> dijkstra(int n, const vector<vector<int>>& edges, int start) {
    vector<vector<pair<int, int>>> graph(n);
    for (const auto& edge : edges) graph[edge[0]].push_back({edge[1], edge[2]});
    const long long infinity = LLONG_MAX / 4;
    vector<long long> distance(n, infinity);
    using Entry = pair<long long, int>;
    priority_queue<Entry, vector<Entry>, greater<Entry>> pending;
    distance[start] = 0;
    pending.push({0, start});
    while (!pending.empty()) {
        auto [cost, node] = pending.top();
        pending.pop();
        if (cost != distance[node]) continue;
        for (auto [next, weight] : graph[node]) {
            if (cost + weight < distance[next]) {
                distance[next] = cost + weight;
                pending.push({distance[next], next});
            }
        }
    }

    vector<optional<long long>> result(n);
    for (int node = 0; node < n; ++node) {
        if (distance[node] != infinity) result[node] = distance[node];
    }
    return result;
}

