long long networkDelay(int n, const vector<vector<int>>& times, int source) {
    vector<vector<pair<int, int>>> graph(n + 1);
    for (const auto& edge : times) graph[edge[0]].push_back({edge[1], edge[2]});
    const long long infinity = LLONG_MAX / 4;
    vector<long long> distance(n + 1, infinity);
    using Entry = pair<long long, int>;
    priority_queue<Entry, vector<Entry>, greater<Entry>> pending;
    distance[source] = 0;
    pending.push({0, source});
    while (!pending.empty()) {
        auto [cost, node] = pending.top();
        pending.pop();
        if (cost != distance[node]) continue;
        for (auto [next, weight] : graph[node]) {
            if (cost + weight < distance[next]) {
                distance[next] = cost + weight;
                pending.push({distance[next], next});
            }
        }
    }
    long long answer = *max_element(distance.begin() + 1, distance.end());
    return answer == infinity ? -1 : answer;
}

