using namespace std;

long long minimumEffortPath(const vector<vector<int>>& heights) {
    int rows = heights.size(), cols = heights[0].size();
    vector<vector<long long>> effort(rows, vector<long long>(cols, LLONG_MAX));
    using Entry = tuple<long long, int, int>;
    priority_queue<Entry, vector<Entry>, greater<Entry>> pending;
    effort[0][0] = 0;
    pending.emplace(0, 0, 0);
    const int dr[] = {1, -1, 0, 0}, dc[] = {0, 0, 1, -1};
    while (!pending.empty()) {
        auto [cost, r, c] = pending.top();
        pending.pop();
        if (cost != effort[r][c]) continue;
        if (r == rows - 1 && c == cols - 1) return cost;
        for (int direction = 0; direction < 4; ++direction) {
            int nr = r + dr[direction], nc = c + dc[direction];
            if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) continue;
            long long next = max(cost, llabs(1LL * heights[r][c] - heights[nr][nc]));
            if (next < effort[nr][nc]) {
                effort[nr][nc] = next;
                pending.emplace(next, nr, nc);
            }
        }
    }
    return 0;
}

