class DisjointSet {
    vector<int> parent, size;
public:
    explicit DisjointSet(int n) : parent(n), size(n, 1) {
        iota(parent.begin(), parent.end(), 0);
    }
    int find(int node) {
        if (parent[node] != node) parent[node] = find(parent[node]);
        return parent[node];
    }
    bool unite(int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b) return false;
        if (size[a] < size[b]) swap(a, b);
        parent[b] = a;
        size[a] += size[b];
        return true;
    }
};

vector<optional<bool>> connectivityQueries(int n, const vector<ConnectivityOperation>& operations) {
    DisjointSet sets(n);
    vector<optional<bool>> answers;
    for (const auto& operation : operations) {
        if (operation.type == "union") {
            sets.unite(operation.a, operation.b);
            answers.push_back(nullopt);
        } else {
            answers.push_back(sets.find(operation.a) == sets.find(operation.b));
        }
    }
    return answers;
}

