using namespace std;

class DisjointSet {
    vector<int> parent, size;
public:
    explicit DisjointSet(int n) : parent(n), size(n, 1) {
        iota(parent.begin(), parent.end(), 0);
    }
    int find(int node) {
        if (parent[node] != node) parent[node] = find(parent[node]);
        return parent[node];
    }
    bool unite(int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b) return false;
        if (size[a] < size[b]) swap(a, b);
        parent[b] = a;
        size[a] += size[b];
        return true;
    }
};

vector<int> redundantConnection(int n, const vector<vector<int>>& edges) {
    DisjointSet sets(n);
    for (const auto& edge : edges) {
        if (!sets.unite(edge[0], edge[1])) return edge;
    }
    return {};
}

