int shortestBinaryMatrixPath(vector<vector<int>> grid) {
    int n = grid.size();
    if (n == 0 || grid[0][0] || grid[n - 1][n - 1]) return -1;
    vector<tuple<int, int, int>> pending{{0, 0, 1}};
    grid[0][0] = 1;
    for (size_t head = 0; head < pending.size(); ++head) {
        auto [r, c, distance] = pending[head];
        if (r == n - 1 && c == n - 1) return distance;
        for (int dr = -1; dr <= 1; ++dr) {
            for (int dc = -1; dc <= 1; ++dc) {
                int nr = r + dr, nc = c + dc;
                if (nr >= 0 && nr < n && nc >= 0 && nc < n && grid[nr][nc] == 0) {
                    grid[nr][nc] = 1;
                    pending.emplace_back(nr, nc, distance + 1);
                }
            }
        }
    }
    return -1;
}

