using namespace std;

vector<optional<long long>> shortestDagPaths(int n, const vector<vector<int>>& edges, int start) {
    vector<vector<pair<int, int>>> adjacency(n);
    vector<int> indegree(n, 0), pending;
    for (const auto& edge : edges) {
        adjacency[edge[0]].push_back({edge[1], edge[2]});
        ++indegree[edge[1]];
    }
    for (int vertex = 0; vertex < n; ++vertex) {
        if (indegree[vertex] == 0) pending.push_back(vertex);
    }
    vector<optional<long long>> distance(n, nullopt);
    distance[start] = 0;
    for (size_t head = 0; head < pending.size(); ++head) {
        int vertex = pending[head];
        for (auto [neighbor, weight] : adjacency[vertex]) {
            if (distance[vertex]) {
                long long candidate = *distance[vertex] + weight;
                if (!distance[neighbor] || candidate < *distance[neighbor]) {
                    distance[neighbor] = candidate;
                }
            }
            if (--indegree[neighbor] == 0) pending.push_back(neighbor);
        }
    }
    return distance;
}

