using namespace std;

int minimumMultiplications(const vector<int>& multipliers, int start, int end) {
    constexpr int modulus = 100000;
    vector<int> distance(modulus, -1), pending{start};
    distance[start] = 0;
    for (size_t head = 0; head < pending.size(); ++head) {
        int value = pending[head];
        if (value == end) return distance[value];
        for (int multiplier : multipliers) {
            int next = static_cast<int>(1LL * value * multiplier % modulus);
            if (distance[next] == -1) {
                distance[next] = distance[value] + 1;
                pending.push_back(next);
            }
        }
    }
    return -1;
}

