using namespace std;

int largestIslandAfterFlip(vector<vector<int>> grid) {
    int n = static_cast<int>(grid.size()), nextLabel = 2, best = 0;
    vector<int> areas(2, 0);
    int dr[] = {1, -1, 0, 0}, dc[] = {0, 0, 1, -1};
    for (int row = 0; row < n; ++row) {
        for (int column = 0; column < n; ++column) {
            if (grid[row][column] != 1) continue;
            vector<pair<int, int>> stack{{row, column}};
            grid[row][column] = nextLabel;
            int area = 0;
            while (!stack.empty()) {
                auto [r, c] = stack.back();
                stack.pop_back();
                ++area;
                for (int direction = 0; direction < 4; ++direction) {
                    int nr = r + dr[direction], nc = c + dc[direction];
                    if (nr >= 0 && nr < n && nc >= 0 && nc < n && grid[nr][nc] == 1) {
                        grid[nr][nc] = nextLabel;
                        stack.push_back({nr, nc});
                    }
                }
            }
            areas.push_back(area);
            ++nextLabel;
            best = max(best, area);
        }
    }
    for (int row = 0; row < n; ++row) {
        for (int column = 0; column < n; ++column) {
            if (grid[row][column] != 0) continue;
            set<int> neighbors;
            for (int direction = 0; direction < 4; ++direction) {
                int r = row + dr[direction], c = column + dc[direction];
                if (r >= 0 && r < n && c >= 0 && c < n) neighbors.insert(grid[r][c]);
            }
            int joined = 1;
            for (int label : neighbors) joined += areas[label];
            best = max(best, joined);
        }
    }
    return best;
}

