using namespace std;

vector<vector<int>> insertInterval(const vector<vector<int>>& intervals, const vector<int>& newInterval) {
    int left = newInterval[0], right = newInterval[1], index = 0;
    int n = intervals.size();
    vector<vector<int>> merged;
    while (index < n && intervals[index][1] < left) merged.push_back(intervals[index++]);
    while (index < n && intervals[index][0] <= right) {
        left = min(left, intervals[index][0]);
        right = max(right, intervals[index][1]);
        ++index;
    }
    merged.push_back({left, right});
    while (index < n) merged.push_back(intervals[index++]);
    return merged;
}

