#include <algorithm>
#include <stdexcept>
#include <vector>

using namespace std;

int minimumJumps(const vector<int>& jumps) {
    int n = jumps.size();
    if (n <= 1) return 0;
    long long frontierEnd = 0, farthest = 0;
    int count = 0;
    for (int index = 0; index < n - 1; ++index) {
        if (index > farthest) return -1;
        farthest = max(farthest, 1LL * index + jumps[index]);
        if (index == frontierEnd) {
            if (farthest == frontierEnd) return -1;
            ++count;
            frontierEnd = farthest;
            if (frontierEnd >= n - 1) return count;
        }
    }
    return -1;
}

