using namespace std;

int gasStationStart(const vector<int>& gas, const vector<int>& cost) {
    long long total = 0, tank = 0;
    int start = 0;
    for (int index = 0; index < static_cast<int>(gas.size()); ++index) {
        long long gain = 1LL * gas[index] - cost[index];
        total += gain;
        tank += gain;
        if (tank < 0) {
            start = index + 1;
            tank = 0;
        }
    }
    if (gas.empty() || total < 0) return -1;
    return start % static_cast<int>(gas.size());
}

