using namespace std;

long long robCircularHouses(const vector<int>& values) {
    int n = values.size();
    if (n == 0) return 0;
    if (n == 1) return values[0];
    auto robRange = [&](int left, int right) {
        long long twoBack = 0, oneBack = 0;
        for (int i = left; i <= right; ++i) {
            long long current = max(oneBack, twoBack + values[i]);
            twoBack = oneBack;
            oneBack = current;
        }
        return oneBack;
    };
    return max(robRange(0, n - 2), robRange(1, n - 1));
}

