long long countTargetSumAssignments(const vector<int>& nums, int target) {
    unordered_map<long long, long long> ways{{0, 1}};
    for (int value : nums) {
        unordered_map<long long, long long> next;
        for (auto [sum, count] : ways) {
            next[sum + value] += count;
