using namespace std;

int minimumEggDropMoves(int eggs, long long floors) {
    vector<long long> coverage(eggs + 1, 0);
    int moves = 0;
    while (coverage[eggs] < floors) {
        ++moves;
        for (int available = eggs; available > 0; --available) {
            // Saturate without overflowing while combining the two possible outcomes.
            long long below = coverage[available - 1];
            long long above = coverage[available];
            coverage[available] = above >= floors - below - 1 ? floors : above + below + 1;
        }
    }
    return moves;
}

