bool wildcardMatch(const string& text, const string& pattern) {
    vector<bool> matches(pattern.size() + 1, false);
    matches[0] = true;
    for (int j = 1; j <= static_cast<int>(pattern.size()); ++j) {
        matches[j] = matches[j - 1] && pattern[j - 1] == '*';
