        bool diagonal = matches[0];
        matches[0] = false;
        for (int j = 1; j <= static_cast<int>(pattern.size()); ++j) {
            bool above = matches[j];
            if (pattern[j - 1] == '*') matches[j] = matches[j] || matches[j - 1];
