int countTrueParenthesizations(const string& expression) {
    constexpr long long mod = 1000000007;
    int operands = static_cast<int>((expression.size() + 1) / 2);
    vector<vector<array<long long, 2>>> ways(
        operands, vector<array<long long, 2>>(operands, {0, 0}));
    for (int i = 0; i < operands; ++i) ways[i][i][expression[2 * i] == 'T'] = 1;
    for (int length = 2; length <= operands; ++length) {
        for (int left = 0; left + length <= operands; ++left) {
            int right = left + length - 1;
            for (int split = left; split < right; ++split) {
                char operation = expression[2 * split + 1];
                for (int first = 0; first < 2; ++first) {
                    for (int second = 0; second < 2; ++second) {
                        int result = operation == '&' ? (first & second) :
                                     operation == '|' ? (first | second) : (first ^ second);
                        ways[left][right][result] = (ways[left][right][result] +
                            ways[left][split][first] * ways[split + 1][right][second]) % mod;
                    }
                }
            }
        }
    }
    return static_cast<int>(ways[0][operands - 1][1]);
}

