vector<int> findTwoUniqueNumbers(const vector<int>& nums) {
    uint32_t combined = 0;
    for (int value : nums) combined ^= static_cast<uint32_t>(value);
    // Isolate one bit where the two unique values differ.
    uint32_t differingBit = combined & (~combined + 1);
    int first = 0, second = 0;
    for (int value : nums) {
        if (static_cast<uint32_t>(value) & differingBit) first ^= value;
        else second ^= value;
    }
    if (first > second) swap(first, second);
    return {first, second};
}

