string replaceWords(const vector<string>& roots, const string& sentence) {
    struct Node {
        map<char, int> children;
        bool terminal = false;
    };
    vector<Node> trie(1);
    for (const string& root : roots) {
        int node = 0;
        for (char ch : root) {
            if (!trie[node].children.count(ch)) {
                int child = static_cast<int>(trie.size());
                trie[node].children[ch] = child;
                trie.emplace_back();
            }
            node = trie[node].children[ch];
        }
        trie[node].terminal = true;
    }
    string answer;
    size_t start = 0;
    while (true) {
        size_t space = sentence.find(' ', start);
        string word = sentence.substr(start, space == string::npos ? space : space - start);
        string prefix;
        int node = 0;
        for (char ch : word) {
            auto child = trie[node].children.find(ch);
            if (child == trie[node].children.end()) break;
            node = child->second;
            prefix += ch;
            if (trie[node].terminal) {
                word = prefix;
                break;
            }
        }
        answer += word;
        if (space == string::npos) break;
        answer += ' ';
        start = space + 1;
    }
    return answer;
}

