            if (found == positions.end()) {
                answers.push_back(-1);
            } else {
                entries.splice(entries.end(), entries, found->second);
                answers.push_back(found->second->second);
            }
        } else {
            if (found != positions.end()) {
                entries.erase(found->second);
                positions.erase(found);
            }
            entries.push_back({operation.key, operation.value});
            positions[operation.key] = prev(entries.end());
            if (static_cast<int>(entries.size()) > capacity) {
                positions.erase(entries.front().first);
                entries.pop_front();
            }
