using namespace std;

string longestWordWithEveryPrefix(const vector<string>& words) {
    struct Node {
        array<int, 26> children;
        bool terminal = false;
        Node() { children.fill(-1); }
    };
    vector<Node> trie(1);
    for (const string& word : words) {
        int node = 0;
        for (char ch : word) {
            int letter = ch - 'a';
            if (trie[node].children[letter] == -1) {
                int child = static_cast<int>(trie.size());
                trie[node].children[letter] = child;
                trie.emplace_back();
            }
            node = trie[node].children[letter];
        }
        trie[node].terminal = true;
    }
    string longest;
    for (const string& word : words) {
        int node = 0;
        bool valid = true;
        for (char ch : word) {
            node = trie[node].children[ch - 'a'];
            if (!trie[node].terminal) {
                valid = false;
                break;
            }
        }
        if (valid && (word.size() > longest.size() ||
                     (word.size() == longest.size() && word < longest))) {
            longest = word;
        }
    }
    return longest;
}

