using namespace std;

int findSubstring(const string& text, const string& pattern) {
    if (pattern.empty()) return 0;
    vector<int> prefix(pattern.size(), 0);
    for (int i = 1, matched = 0; i < static_cast<int>(pattern.size()); ++i) {
        while (matched > 0 && pattern[i] != pattern[matched]) {
            matched = prefix[matched - 1];
        }
        if (pattern[i] == pattern[matched]) ++matched;
        prefix[i] = matched;
    }
    for (int i = 0, matched = 0; i < static_cast<int>(text.size()); ++i) {
        while (matched > 0 && text[i] != pattern[matched]) {
            matched = prefix[matched - 1];
        }
        if (text[i] == pattern[matched]) ++matched;
        if (matched == static_cast<int>(pattern.size())) return i - matched + 1;
    }
    return -1;
}

